import test from 'node:test';import assert from 'node:assert/strict';import {standardPip,normalizePip,attachPip,matchPipCrew,pipGroups,pipPalette,pipSvg,pipAnalysis} from '../src/pip.js';
test('PIP saved values are validated; every part can be fitted and reset',()=>{const initial=standardPip();assert.deepEqual(normalizePip({color:'url(bad)',eyes:'unknown'}),initial);assert.deepEqual(normalizePip(null),initial);for(const g of pipGroups)for(const p of g.parts){const c=attachPip(initial,g.id,p.id);assert.equal(c[g.id],p.id);assert.ok(pipSvg(c).includes('<svg'));assert.deepEqual(initial,standardPip())}for(let i=0;i<6;i++)assert.equal(matchPipCrew(initial,i).color,pipPalette[i+1].id);assert.deepEqual(attachPip(initial,'fake','bad'),initial)});
test('schematic layers show distinct travel, tool and eye parts',()=>{for(const slot of ['travel','tool','eyes']){const variants=pipGroups.find(g=>g.id===slot).parts.map(p=>pipSvg({...standardPip(),[slot]:p.id},slot));assert.equal(new Set(variants).size,variants.length)}const arms=pipSvg({...standardPip(),travel:'climber'},'travel');assert.equal((arms.match(/M/g)||[]).length,4)});
test('science formulas are scoped to actual material or clearly named examples',()=>{assert.equal(pipAnalysis('quartz').formula,'SiO₂');assert.match(pipAnalysis('quartz').note,/not a separate quartz molecule/);assert.match(pipAnalysis('iron').note,/Example: magnetite/);assert.match(pipAnalysis('fossil').fact,/does not have one chemical formula/);assert.equal(pipAnalysis('fake'),null);for(const id of ['quartz','iron','fossil']){assert.ok(pipAnalysis(id,'lens').detail);assert.ok(pipAnalysis(id,'sampler').detail);assert.ok(pipAnalysis(id).atoms.every(a=>a[2]>0))}});
